package clip

import (
	"encoding/binary"
	"strings"
)

// presenceOnly formats mean "do not sync" when the format exists at all.
var presenceOnly = []string{
	"excludeclipboardcontentfrommonitorprocessing",
	"org.nspasteboard.concealedtype",
	"org.nspasteboard.transienttype",
	"org.nspasteboard.autogeneratedtype",
}

// valueZero formats are skipped only when their DWORD payload is 0.
var valueZero = []string{
	"canincludeinclipboardhistory",
	"canuploadtocloudclipboard",
}

// Sensitive reports whether a clipboard snapshot must not be recorded or synced.
// read is used for Windows DWORD formats. A missing or unreadable value is
// treated as sensitive: failing open would sync a password.
func Sensitive(formats []string, read func(name string) ([]byte, bool)) (bool, string) {
	for _, raw := range formats {
		name := strings.ToLower(strings.TrimSpace(raw))
		if name == "" {
			continue
		}
		for _, blocked := range presenceOnly {
			if name == blocked || strings.Contains(name, blocked) {
				return true, raw
			}
		}
	}
	for _, raw := range formats {
		name := strings.ToLower(strings.TrimSpace(raw))
		for _, blocked := range valueZero {
			if name != blocked && !strings.HasSuffix(name, blocked) {
				continue
			}
			buf, ok := read(raw)
			if !ok || dwordZero(buf) {
				return true, raw
			}
		}
	}
	return false, ""
}

func dwordZero(b []byte) bool {
	if len(b) < 4 {
		return true
	}
	return binary.LittleEndian.Uint32(b[:4]) == 0
}

func HasImage(formats []string) bool {
	for _, raw := range formats {
		name := strings.ToLower(strings.TrimSpace(raw))
		for _, known := range imageFormatNames {
			if name == known {
				return true
			}
		}
	}
	return false
}

func HasText(formats []string) bool {
	for _, raw := range formats {
		switch strings.ToLower(strings.TrimSpace(raw)) {
		case "text/plain", "public.utf8-plain-text", "public.plain-text",
			"nsstringpboardtype", "text":
			return true
		}
	}
	return false
}
